// ======================= PERÍODOS (MÊS + ANO) =======================
const pad = (n) => String(n).padStart(2, '0');
const montarPeriodo = (ano, mes) => ano + '-' + pad(mes);
const lerPeriodo = (p) => {
  const partes = String(p).split('-');
  return { ano: parseInt(partes[0], 10), mes: parseInt(partes[1], 10) };
};
const somarMeses = (p, n) => {
  const { ano, mes } = lerPeriodo(p);
  const total = ano * 12 + (mes - 1) + n;
  return montarPeriodo(Math.floor(total / 12), (total % 12) + 1);
};
const diasNoMes = (ano, mes) => new Date(ano, mes, 0).getDate();
const PERIODO_MIN = montarPeriodo(ANO_INICIAL, 1);
const PERIODO_MAX = montarPeriodo(ANO_FINAL, 12);
const limitarPeriodo = (p) => (p < PERIODO_MIN ? PERIODO_MIN : p > PERIODO_MAX ? PERIODO_MAX : p);

const PERIODOS = [];
for (let a = ANO_INICIAL; a <= ANO_FINAL; a++) {
  for (let m = 1; m <= 12; m++) PERIODOS.push({ id: montarPeriodo(a, m), ano: a, mes: m });
}
const ANOS = [];
for (let a = ANO_INICIAL; a <= ANO_FINAL; a++) ANOS.push(a);

const dataTxt = (t) => {
  const { ano, mes } = lerPeriodo(t.periodo);
  const d = Math.min(t.dia || 1, diasNoMes(ano, mes));
  return pad(d) + '/' + pad(mes);
};

