// Formata em padrão brasileiro: R$ 1.234,56
const moeda = (n) => {
  const v = Number(n) || 0;
  const [inteiro, dec] = Math.abs(v).toFixed(2).split('.');
  return (v < 0 ? '-' : '') + 'R$ ' + inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec;
};

const numeroCSV = (n) => (Number(n) || 0).toFixed(2).replace('.', ',');

const aviso = (titulo, msg) => {
  if (Platform.OS === 'web') window.alert(titulo + '\n' + msg);
  else Alert.alert(titulo, msg);
};

const vibrar = (padrao) => {
  if (Platform.OS === 'web') return;
  try {
    Vibration.vibrate(padrao);
  } catch (e) {}
};

const esc = (s) =>
  String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const baixarArquivoWeb = (nome, conteudo, tipo) => {
  const blob = new Blob([conteudo], { type: tipo });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = nome;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

// Dados antigos (sem ano/categoria) são convertidos automaticamente
const migrarTransacao = (t) => {
  if (t.periodo) return { categoria: 'outros', ...t };
  const d = new Date(Number(t.id));
  const valida = !isNaN(d.getTime());
  let ano = valida ? d.getFullYear() : ANO_INICIAL;
  if (ano < ANO_INICIAL) ano = ANO_INICIAL;
  if (ano > ANO_FINAL) ano = ANO_FINAL;
  const mes = t.mes || pad(valida ? d.getMonth() + 1 : 1);
  const resto = { ...t };
  delete resto.mes;
  return { categoria: 'outros', ...resto, periodo: ano + '-' + mes, dia: valida ? d.getDate() : 1 };
};

const migrarRenda = (r) => {
  if (r.periodo) return r;
  const d = new Date(Number(r.id));
  const valida = !isNaN(d.getTime());
  let ano = valida ? d.getFullYear() : ANO_INICIAL;
  if (ano < ANO_INICIAL) ano = ANO_INICIAL;
  if (ano > ANO_FINAL) ano = ANO_FINAL;
  const mes = r.mes || pad(valida ? d.getMonth() + 1 : 1);
  const resto = { ...r };
  delete resto.mes;
  return { ...resto, periodo: ano + '-' + mes };
};

