// ======================= CÁLCULOS TRABALHISTAS (tabelas 2026) =======================
const arred = (n) => Math.round((Number(n) || 0) * 100) / 100;
const FAIXAS_INSS = [[1621.0, 0.075], [2902.84, 0.09], [4354.27, 0.12], [8475.55, 0.14]];

const calcINSS = (bruto) => {
  const base = Math.min(Math.max(bruto, 0), 8475.55);
  let anterior = 0;
  let total = 0;
  FAIXAS_INSS.forEach(([limite, aliquota]) => {
    if (base > anterior) total += (Math.min(base, limite) - anterior) * aliquota;
    anterior = limite;
  });
  return arred(total);
};

const calcIRRF = (bruto, inss, dependentes) => {
  // usa a opção mais vantajosa: deduções legais ou desconto simplificado
  const baseLegal = bruto - inss - dependentes * 189.59;
  const baseSimples = bruto - 607.2;
  const base = Math.max(0, Math.min(baseLegal, baseSimples));
  let imposto = 0;
  if (base <= 2428.8) imposto = 0;
  else if (base <= 2826.65) imposto = base * 0.075 - 182.16;
  else if (base <= 3751.05) imposto = base * 0.15 - 394.16;
  else if (base <= 4664.68) imposto = base * 0.225 - 675.49;
  else imposto = base * 0.275 - 908.73;
  imposto = Math.max(0, imposto);
  // redução da Lei 15.270/2025 (isenção até R$ 5.000 e redução gradual até R$ 7.350)
  let reducao = 0;
  if (bruto <= 5000) reducao = imposto;
  else if (bruto <= 7350) reducao = Math.max(0, 978.62 - 0.133145 * bruto);
  reducao = Math.min(reducao, imposto);
  return arred(imposto - reducao);
};

const calc13 = (salario, meses, dependentes) => {
  const bruto = arred((salario / 12) * meses);
  const primeira = arred(bruto / 2); // paga até 30/11, sem descontos
  const inss = calcINSS(bruto);
  const irrf = calcIRRF(bruto, inss, dependentes);
  const segunda = arred(bruto - primeira - inss - irrf); // paga até 20/12, com os descontos
  return { bruto, primeira, inss, irrf, segunda, liquido: arred(primeira + segunda) };
};

const calcFerias = (salario, dias, venderDias, dependentes) => {
  const base = arred((salario / 30) * dias);
  const terco = arred(base / 3);
  const brutoFerias = arred(base + terco);
  const abono = venderDias > 0 ? arred(((salario / 30) * venderDias) * (4 / 3)) : 0; // isento de INSS e IR
  const inss = calcINSS(brutoFerias);
  const irrf = calcIRRF(brutoFerias, inss, dependentes);
  const liquido = arred(brutoFerias - inss - irrf + abono);
  return { base, terco, brutoFerias, abono, inss, irrf, liquido };
};

