        <View style={styles.rodapeAnual}>
          <Text style={styles.rodapeAnualTxt}>Total no ano: <Text style={{ fontWeight: 'bold' }}>{moeda(totalAno)}</Text></Text>
          <Text style={styles.rodapeAnualTxt}>Média mensal: <Text style={{ fontWeight: 'bold' }}>{moeda(mediaMensal)}</Text></Text>
        </View>
